// String returns the Go constant name of the result.
func (r Result) String() string {
	if name, ok := resultNames[r]; ok {
		return name
	}
	return fmt.Sprintf("Result(%d)", int32(r))
}

// goString converts a null-terminated C string to a Go string.
func goString(p *byte) string {
	if p == nil {
		return ""
	}
	var buf []byte
	for ptr := p; *ptr != 0; ptr = (*byte)(ptrAdd(ptr, 1)) {
		buf = append(buf, *ptr)
	}
	return string(buf)
}

// toError converts a Result to an error, returning nil for Success.
func toError(r Result) error {
	if r == Success {
		return nil
	}
	return r
}

